# -*- coding: utf-8 -*-
"""Round91 B11/B12 盲测预测落盘脚本（平台盲测席专用）。逐批写、逐批断言、逐件回读自验。"""
import json, os

PRED_DIR = "/home/hatch/workspace/divination/benchmark/phase3/runs/round91/predictions"

def T(cm=False, ru=False, di=False, reason=""):
    return {"changed_main": cm, "reserve_used": ru, "disputed": di, "reason": reason}

def write_batch(name, cases):
    os.makedirs(PRED_DIR, exist_ok=True)
    for c in cases:
        assert set(c.keys()) == {"case_id","prediction_text","basis","confidence","trigger"}, c["case_id"]
        assert 0.0 <= c["confidence"] <= 1.0, c["case_id"]
        tr = c["trigger"]
        assert set(tr.keys()) == {"changed_main","reserve_used","disputed","reason"}
        assert all(isinstance(tr[k], bool) for k in ("changed_main","reserve_used","disputed"))
        p = os.path.join(PRED_DIR, c["case_id"] + ".json")
        with open(p, "w", encoding="utf-8") as f:
            json.dump(c, f, ensure_ascii=False, indent=1)
    # 逐件回读自验
    for c in cases:
        p = os.path.join(PRED_DIR, c["case_id"] + ".json")
        d = json.load(open(p, encoding="utf-8"))
        assert d["case_id"] == c["case_id"] and d["prediction_text"] and d["basis"]
        assert 0.0 <= d["confidence"] <= 1.0
    print(name, "written+verified:", len(cases))

